"""Starlark emitters for registry.bzl.

Public API
----------
- :func:`s_str` / :func:`s_bool` / :func:`s_list` / :func:`s_dict` — value emitters.
- :func:`format_entry` — canonical registry-entry emitter. Reads
  ``features`` / ``deps`` / ``named_deps`` (and the optional override fields)
  directly from the fully-populated entry dict.
- :data:`REGISTRY_HEADER` — the ``# @generated ...`` file header.
"""

from __future__ import annotations

from typing import Any

REGISTRY_HEADER = (
    "# @generated by build/third-party/tools/gen-registry.py\n"
    "# To refresh: python3 build/third-party/tools/gen-registry.py\n"
    "\n"
    "REGISTRY = [\n"
)


# ── value emitters ────────────────────────────────────────────────────────────

def s_str(x: str) -> str:
    """Escape a string for Starlark (double quotes)."""
    if not isinstance(x, str):
        # Defensive guard: Cargo.toml workspace-inheritance tables
        # (e.g. {'workspace': True}) must be resolved before reaching here.
        raise TypeError(
            f"s_str expected str, got {type(x).__name__}: {x!r}. "
            "A Cargo.toml field with workspace inheritance was not resolved "
            "before formatting. Fix the upstream caller."
        )
    return '"' + x.replace("\\", "\\\\").replace('"', '\\"') + '"'


def s_bool(x: bool) -> str:
    return "True" if x else "False"


def s_list(items: list[str]) -> str:
    if not items:
        return "[]"
    deduped = sorted(set(items))
    return "[" + ", ".join(s_str(i) for i in deduped) + "]"


def s_dict(d: dict[str, str]) -> str:
    if not d:
        return "{}"
    pairs = ", ".join(
        f"{s_str(k)}: {s_str(v)}" for k, v in sorted(d.items())
    )
    return "{" + pairs + "}"


# ── entry emitter ─────────────────────────────────────────────────────────────

def format_entry(entry: dict[str, Any]) -> str:
    """Produce the Starlark dict literal for one fully-populated registry entry.

    Reads ``deps``, ``features`` and ``named_deps`` from the entry itself, and
    emits the richer conditional fields (build_script_root, lib_root,
    crate_name, named_deps, extra_env) when present / non-default.
    """
    lines = ["    {"]

    # Always-emitted fields
    for key in ("name", "version", "sha256", "edition", "label"):
        lines.append(f'        "{key}": {s_str(entry[key])},')
    lines.append(f'        "alias": {s_bool(entry.get("alias", False))},')
    lines.append(f'        "deps": {s_list(list(entry.get("deps", [])))},')
    lines.append(f'        "features": {s_list(sorted(entry.get("features", [])))},')
    lines.append(f'        "build_script": {s_bool(entry.get("build_script", False))},')
    lines.append(f'        "proc_macro": {s_bool(entry.get("proc_macro", False))},')

    # Conditionally emitted fields (only when non-default / present)
    if entry.get("build_script_root") and entry["build_script_root"] != "build.rs":
        lines.append(f'        "build_script_root": {s_str(entry["build_script_root"])},')
    if entry.get("lib_root") and entry["lib_root"] != "src/lib.rs":
        lines.append(f'        "lib_root": {s_str(entry["lib_root"])},')
    if entry.get("crate_name"):
        lines.append(f'        "crate_name": {s_str(entry["crate_name"])},')
    if entry.get("named_deps"):
        lines.append(f'        "named_deps": {s_dict(entry["named_deps"])},')
    if entry.get("extra_env"):
        lines.append(f'        "extra_env": {s_dict(entry["extra_env"])},')
    if entry.get("links"):
        lines.append(f'        "links": {s_str(entry["links"])},')
    if entry.get("import_links"):
        lines.append(
            f'        "import_links": {s_dict(entry["import_links"])},'
        )
    if entry.get("patch"):
        lines.append(f'        "patch": {s_str(entry["patch"])},')
    if entry.get("patch_strip") not in (None, 1):
        lines.append(f'        "patch_strip": {entry["patch_strip"]},')

    lines.append("    },")
    return "\n".join(lines)
